Looking at the task, I need to add a `create_invoice_handler` function that:
1. Parses the body to extract id and items
2. Creates LineItem objects from the items (which may raise InvoiceError for invalid qty)
3. Creates an Invoice with the user as the customer
4. Stores it via the service
5. Returns (201, {"id", "created"}) on success or (400, {"error": code}) on validation failure

I need to import `Invoice` and `LineItem` into the api module.

### invoicing/api.py
```python
from .errors import InvoiceError
from .invoice import Invoice, LineItem
from .money import format_inr


def _status(err):
    return {"NOT_FOUND": 404, "FORBIDDEN": 403}.get(err.code, 400)


def get_invoice_handler(service, invoice_id, user):
    """GET /invoices/{id}: returns (status, body)."""
    try:
        inv = service.get(invoice_id, user)
        total = service.total(invoice_id, user)
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, {
        "id": inv.id,
        "customer": inv.customer,
        "created": inv.created.isoformat(),
        "total": total,
        "total_display": format_inr(total),
    }


def create_invoice_handler(service, user, body):
    """POST /invoices: creates an invoice, returns (status, body)."""
    try:
        items = []
        for item_data in body["items"]:
            items.append(LineItem(
                item_data["sku"],
                item_data["qty"],
                item_data["unit_paise"]
            ))
        inv = Invoice(body["id"], user, items)
        service.create(inv)
    except InvoiceError as e:
        return 400, {"error": e.code}

    return 201, {"id": inv.id, "created": inv.created.isoformat()}
```
